<script>
const product = document.getElementById('product_id'); const quantity = document.getElementById('quantity'); const total = document.getElementById('sale-total'); const note = document.getElementById('stock-note');
function updateSalePreview(){ const option = product.options[product.selectedIndex]; const price = Number(option?.dataset.price || 0); const stock = Number(option?.dataset.stock || 0); const qty = Math.max(1, Number(quantity.value || 1)); total.textContent = new Intl.NumberFormat('en-PH', {style:'currency',currency:'PHP'}).format(price * qty); note.textContent = product.value ? `${stock} unit${stock === 1 ? '' : 's'} available · requested ${qty}` : 'Choose a product to see available stock.'; quantity.max = stock || 1; } product?.addEventListener('change', updateSalePreview); quantity?.addEventListener('input', updateSalePreview); updateSalePreview();
</script>
